function openTemplateDialog(){const modal=$('#templateModal');modal.classList.add('open');modal.setAttribute('aria-hidden','false');$('#templateName').value=project.name||'';renderBuiltinTemplates();const supported=typeof window.showDirectoryPicker==='function';$('#chooseTemplateFolder').disabled=!supported;if(!supported){$('#templateFolderName').textContent='Folder access unavailable';$('#templateFolderHint').textContent='Save template will download a file to your Downloads folder.';$('#templateList').innerHTML='<div class="template-list-empty">Use Save template to download a reusable template file.</div>'}else{templateStatus('Saved templates stay in the folder you choose.');restoreTemplateDirectory()}setTimeout(()=>$('#templateName').focus(),80)}
