async function chooseTemplateDirectory(){if(!window.showDirectoryPicker)return;try{const handle=await window.showDirectoryPicker({id:'card-studio-templates',mode:'readwrite'});templateDirectory=handle;await storeTemplateDirectory(handle);$('#templateFolderName').textContent=handle.name;$('#templateFolderHint').textContent='Local template folder selected';await refreshTemplateList();templateStatus('Folder ready. Save templates here for reuse.')}catch(e){if(e.name!=='AbortError')templateStatus('Could not access that folder.',true)}}
async function refreshTemplateList(){const list=$('#templateList');if(!templateDirectory){list.innerHTML='<div class="template-list-empty">Choose a folder to see saved templates.</div>';return}try{const permission=await templateDirectory.queryPermission({mode:'readwrite'});if(permission!=='granted'){list.innerHTML='<div class="template-list-empty">Choose this folder again to reconnect.</div>';return}const files=[];for await(const [name,handle] of templateDirectory.entries()){if(handle.kind==='file'&&name.toLowerCase().endsWith('.cardtemplate.json'))files.push({name,handle})}files.sort((a,b)=>a.name.localeCompare(b.name));list.replaceChildren();if(!files.length){list.innerHTML='<div class="template-list-empty">No templates yet. Save your first template here.</div>';return}for(const item of files){const row=document.createElement('div');row.className='template-row';const icon=document.createElement('span');icon.className='template-file-icon';icon.textContent='▧';const title=document.createElement('span');title.className='template-row-name';title.textContent=item.name.replace(/\.cardtemplate\.json$/i,'');const load=document.createElement('button');load.className='btn quiet';load.textContent='Load';load.onclick=()=>loadTemplate(item.handle,title.textContent);row.append(icon,title,load);list.append(row)}}catch(e){list.innerHTML='<div class="template-list-empty">Unable to read this folder. Choose it again to reconnect.</div>';templateStatus('Folder access needs to be restored.',true)}}
async function saveTemplate(){const name=$('#templateName').value.trim();if(!name){templateStatus('Enter a template name first.',true);$('#templateName').focus();return}if(!window.showDirectoryPicker){const payload={format:'card-studio-template',version:1,name,design:structuredClone(project),createdAt:new Date().toISOString()};download(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),name+'.cardtemplate.json');templateStatus('Template file downloaded.');toast('Template downloaded');return}if(!templateDirectory){await chooseTemplateDirectory();if(!templateDirectory)return}try{let permission=await templateDirectory.queryPermission({mode:'readwrite'});if(permission!=='granted')permission=await templateDirectory.requestPermission({mode:'readwrite'});if(permission!=='granted'){templateStatus('Allow folder access to save this template.',true);return}const filename=name.replace(/[\\/:*?"<>|]/g,'-')+'.cardtemplate.json',handle=await templateDirectory.getFileHandle(filename,{create:true}),writable=await handle.createWritable(),payload={format:'card-studio-template',version:1,name,design:structuredClone(project),createdAt:new Date().toISOString()};await writable.write(JSON.stringify(payload,null,2));await writable.close();$('#templateFolderHint').textContent='Local template folder selected';await refreshTemplateList();templateStatus(`“${name}” saved to ${templateDirectory.name}.`);toast('Template saved locally')}catch(e){templateStatus(e.name==='AbortError'?'Save canceled.':'Could not save template to that folder.',true)}}
$('#saveTemplate').onclick=openTemplateDialog;$('#closeTemplate').onclick=closeTemplateDialog;$('#templateScrim').onclick=closeTemplateDialog;$('#chooseTemplateFolder').onclick=chooseTemplateDirectory;$('#refreshTemplates').onclick=refreshTemplateList;$('#confirmSaveTemplate').onclick=saveTemplate;
$('#fontFamily').onchange=e=>applyTextStyle('font',e.target.value);$('#fontSize').onchange=e=>applyTextStyle('size',Math.max(6,Math.min(120,Number(e.target.value)||6)));$('#fontColor').oninput=e=>applyTextStyle('color',e.target.value);$$('[data-format]').forEach(b=>b.onclick=()=>{const key=b.dataset.format,el=selectedElement();if(!el)return;const active=key==='bold'?(el.bold??(Number(el.weight||400)>=600)):!!el[key];applyTextStyle(key,!active)});$$('[data-align]').forEach(b=>b.onclick=()=>applyTextStyle('align',b.dataset.align));
function openAboutDialog(){const modal=$('#aboutModal');modal.classList.add('open');modal.setAttribute('aria-hidden','false');setTimeout(()=>$('#aboutOk').focus(),80)}
function closeAboutDialog(){const modal=$('#aboutModal');if(!modal.classList.contains('open'))return;modal.classList.remove('open');modal.setAttribute('aria-hidden','true');$('#aboutButton').focus()}
$('#aboutButton').onclick=openAboutDialog;$('#closeAbout').onclick=closeAboutDialog;$('#aboutOk').onclick=closeAboutDialog;$('#aboutScrim').onclick=closeAboutDialog;
// Keyboard shortcuts stay out of text fields and preserve browser editing behavior.
function duplicateSelected(){const el=selectedElement();if(!el)return;const copy=structuredClone(el);copy.id=uid();copy.name=(el.name||el.type)+' copy';copy.x=Math.min(W-copy.w,el.x+12);copy.y=Math.min(H-copy.h,el.y+12);currentElements().push(copy);selected=copy.id;render();canvas.querySelector(`[data-id="${copy.id}"]`)?.focus()}
window.addEventListener('keydown',e=>{const target=e.target,tag=target?.tagName||'',typing=['INPUT','TEXTAREA','SELECT'].includes(tag)||target?.isContentEditable,mod=e.metaKey||e.ctrlKey;if(e.key==='Escape'){closePrintDialog();closeTemplateDialog();closeAboutDialog();return}if(typing)return;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?$('#redoAction').click():$('#undoAction').click();return}if(mod&&(e.key.toLowerCase()==='y')){e.preventDefault();$('#redoAction').click();return}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();return}if(e.altKey&&(e.key==='1'||e.key==='2')){e.preventDefault();face=e.key==='1'?'front':'back';selected=null;render();canvas.focus();return}if((e.key==='Delete'||e.key==='Backspace')&&selected){e.preventDefault();deleteSelected();return}const focusedCanvas=target===canvas||target?.classList?.contains('card-object');if(focusedCanvas&&selected&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){const el=selectedElement();if(!el||el.locked)return;e.preventDefault();const {w:stepX,h:stepY}=pxToUnits(e.shiftKey?10:1,e.shiftKey?10:1);if(e.key==='ArrowLeft')el.x=Math.max(0,el.x-stepX);if(e.key==='ArrowRight')el.x=Math.min(W-el.w,el.x+stepX);if(e.key==='ArrowUp')el.y=Math.max(0,el.y-stepY);if(e.key==='ArrowDown')el.y=Math.min(H-el.h,el.y+stepY);render();canvas.querySelector(`[data-id="${el.id}"]`)?.focus()}});
$('#projectFile').onchange=e=>{const f=e.target.files[0];if(!f)return;const reader=new FileReader();reader.onload=()=>{try{project=normalizeProject(JSON.parse(reader.result));selected=null;face='front';render();toast('Project opened')}catch{toast('That project file is invalid or unsupported')} };reader.readAsText(f);e.target.value=''};
async function loadTemplate(handle,name){try{const permission=await templateDirectory.requestPermission({mode:'readwrite'});if(permission!=='granted'){templateStatus('Allow folder access to load this template.',true);return}const file=await handle.getFile(),data=JSON.parse(await file.text()),design=normalizeProject(data.design||data);if(!confirm(`Load “${name}”? This replaces the current card design.`))return;project=design;selected=null;face='front';render();closeTemplateDialog();toast('Template loaded')}catch{templateStatus('Could not open this template file. It may be invalid or unsupported.',true)}}
(async()=>{await loadLocal();loadPrintSettings();render();if(recoveryBackup)showStorageWarning('Your last saved design could not be opened, so a blank card was started. The old design was kept as a backup — download it below to recover it.')})();
const themeToggle=$('#themeToggle');function setTheme(theme){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';themeToggle.textContent=dark?'☼ Light':'◐ Dark';themeToggle.setAttribute('aria-pressed',String(dark));themeToggle.setAttribute('aria-label',dark?'Switch to light theme':'Switch to dark theme');try{localStorage.setItem('cardStudioTheme',dark?'dark':'light')}catch{}}
let savedTheme='light';try{savedTheme=localStorage.getItem('cardStudioTheme')||'light'}catch{}setTheme(savedTheme);themeToggle.onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');
